const assert = require("assert");
const { siraylaIsle, tekrarDene, say, ortalama, grupla } = require("./islem.js");

(async () => {
  // siraylaIsle: sıralı çalışma (bir çağrı bitmeden sonrakine geçmez)
  const siralar = [];
  await siraylaIsle([1,2,3], async x => { siralar.push("start"+x); await new Promise(r=>setTimeout(r,x*50)); siralar.push("end"+x); });
  assert.deepStrictEqual(siralar, ["start1","end1","start2","end2","start3","end3"], "sıralı çalışmalı");
  const r = await siraylaIsle([1,2,3], async x => x*10);
  assert.deepStrictEqual(r, [10,20,30]);

  // tekrarDene: en fazla deneme kez çağrılır (deneme=3 -> tam 3 çağrı) ve SON hatayı fırlatır
  let c1 = 0;
  await assert.rejects(tekrarDene(async () => { c1++; throw new Error("hata"+c1); }, 3), e => /hata3$/.test(e.message));
  assert.strictEqual(c1, 3, "deneme=3 iken tam 3 kez çağrılmalı");

  // başarılı deneme: ilk başarılı sonucu döner, sonra devam etmez
  let c2 = 0;
  const sonuc = await tekrarDene(async (i) => { c2++; if (c2 < 2) throw new Error("x"); return "ok"+i; }, 5);
  assert.strictEqual(sonuc, "ok1");
  assert.strictEqual(c2, 2);

  // say: doğru sayaçlar
  assert.deepStrictEqual(say(["a","b","a"]), { a:2, b:1 });
  assert.deepStrictEqual(say([7,7,7]), { 7:3 });

  // ortalama: boş dizide 0
  assert.strictEqual(ortalama([]), 0);
  assert.strictEqual(ortalama([2,4]), 3);

  // grupla: anahtara göre gruplar, sıra korunur
  const g = grupla(["elma","armut","erik"], s => s[1]);
  assert.deepStrictEqual(g.l, ["elma"]);
  assert.deepStrictEqual(g.r, ["armut"]);
  assert.deepStrictEqual(Object.keys(g), ["l","r"]);

  console.log("EK KONTROLLER GEÇTİ");
})().catch(e => { console.error("BAŞARISIZ:", e.message); process.exit(1); });

